const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Jabal Qidr and Jabal Bayda are mountains in Saudi Arabia
  // Jabal Bayda (White Mountain) - approximately 24.4°N, 38.5°E
  const jabalBayda = ee.Geometry.Point([38.5, 24.4]);

  // Jabal Qidr - approximately 25.0°N, 37.8°E  
  const jabalQidr = ee.Geometry.Point([37.8, 25.0]);

  const startDate = '2024-04-01';
  const endDate = '2024-04-30';

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Get Sentinel-2 data for Jabal Qidr
  let colQidr = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(jabalQidr)
    .map(maskS2clouds);

  const sizeQidr = await colQidr.size().getInfo();
  console.log(`Jabal Qidr images found: ${sizeQidr}`);

  if (sizeQidr === 0) {
    console.log('No Sentinel-2 data for Jabal Qidr, trying Landsat 8/9...');
    colQidr = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
      .filterDate(startDate, endDate)
      .filterBounds(jabalQidr);
    const sizeQidrL = await colQidr.size().getInfo();
    console.log(`Jabal Qidr Landsat images: ${sizeQidrL}`);
    if (sizeQidrL === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Get Sentinel-2 data for Jabal Bayda
  let colBayda = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(startDate, endDate)
    .filterBounds(jabalBayda)
    .map(maskS2clouds);

  const sizeBayda = await colBayda.size().getInfo();
  console.log(`Jabal Bayda images found: ${sizeBayda}`);

  if (sizeBayda === 0) {
    console.log('No Sentinel-2 data for Jabal Bayda, trying Landsat 8/9...');
    colBayda = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
      .filterDate(startDate, endDate)
      .filterBounds(jabalBayda);
    const sizeBaydaL = await colBayda.size().getInfo();
    console.log(`Jabal Bayda Landsat images: ${sizeBaydaL}`);
    if (sizeBaydaL === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // Create median composites and select RGB bands
  const imgQidr = colQidr.median().select(['B4', 'B3', 'B2']);
  const imgBayda = colBayda.median().select(['B4', 'B3', 'B2']);

  // Calculate mean reflectance (average of RGB) for Jabal Qidr
  const statsQidr = await imgQidr.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: jabalQidr.buffer(1000),
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const countQidr = statsQidr['B4_count'] || 0;
  console.log(`Jabal Qidr valid pixels: ${countQidr}`);

  if (countQidr === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  const meanQidr = (statsQidr['B4_mean'] + statsQidr['B3_mean'] + statsQidr['B2_mean']) / 3;

  // Calculate mean reflectance for Jabal Bayda
  const statsBayda = await imgBayda.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: jabalBayda.buffer(1000),
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const countBayda = statsBayda['B4_count'] || 0;
  console.log(`Jabal Bayda valid pixels: ${countBayda}`);

  if (countBayda === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  const meanBayda = (statsBayda['B4_mean'] + statsBayda['B3_mean'] + statsBayda['B2_mean']) / 3;

  // Validate results
  if (meanQidr === null || meanBayda === null || isNaN(meanQidr) || isNaN(meanBayda)) {
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Jabal Qidr mean reflectance: ${meanQidr.toFixed(2)}`);
  console.log(`Jabal Bayda mean reflectance: ${meanBayda.toFixed(2)}`);

  // Darker color means lower reflectance
  if (meanQidr < meanBayda) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
